var t={en:`An AI agent connected the frontend directly to the database and email provider; the API lost its identity check. Find and fix the trust-boundary mistakes.`,ua:`AI-агент під’єднав фронтенд напряму до бази та поштового провайдера; API втратив перевірку особи. Знайди й усунь порушення меж довіри.`};var r={en:[`Remove browser-to-storage and browser-to-provider shortcuts.`,`Restore the API authentication route and server-controlled mail job.`,`Explain where secrets and permissions are enforced.`],ua:[`Прибери прямі шляхи від браузера до сховища й провайдера.`,`Віднови перевірку через API та серверну задачу листа.`,`Поясни місця зберігання секретів і перевірки прав.`]};var a=[{en:`No frontend→primarydb or frontend→email connection remains.`,ua:`Не залишилось frontend→primarydb чи frontend→email.`},{en:`frontend→api, api→identity and worker→email are restored.`,ua:`Відновлено frontend→api, api→identity та worker→email.`}];var o={remove:[`frontend->api`,`api->identity`,`worker->email`],add:[{from:`frontend`,to:`primarydb`,kind:`data`,label:`Intentional defect / Навмисна помилка`},{from:`frontend`,to:`email`,kind:`sync`,label:`Intentional defect / Навмисна помилка`}]};var i={scenario:t,tasks:r,checks:a,mutations:o};export{a as checks,i as default,o as mutations,t as scenario,r as tasks};